select count(distinct org_id) as client_count_orgs
from read_parquet('data/payments.parquet')
where paid_at >= date '2024-01-01'
  and paid_at <  date '2025-01-01'
  and recorded_at <= date '2025-10-01';

select count(*) as payment_rows_2024
from read_parquet('data/payments.parquet')
where paid_at >= date '2024-01-01'
  and paid_at <  date '2025-01-01'
  and recorded_at <= date '2025-10-01';

select plan_year, size_segment, units_plan, revenue_plan_approved
from read_parquet('data/plan.parquet')
order by plan_year, size_segment

select distinct plan_year, size_segment, units_plan, units_basis,
       revenue_plan_model, revenue_plan_approved, revenue_plan_initial, revenue_plan_premium
from read_parquet('data/plan.parquet')
order by plan_year, size_segment;

select plan_year, size_segment, units_plan, units_basis,
       revenue_plan_model, revenue_plan_premium,
       revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
order by plan_year, size_segment;

select
  sum(amount) as revenue_cash_2024
from read_parquet('data/payments.parquet')
where paid_at >= '2024-01-01' and paid_at < '2025-01-01'
  and recorded_at <= '2025-10-01';

select min(issued_at), max(issued_at), min(paid_at) from
(select i.issued_at, p.paid_at from read_parquet('data/invoices.parquet') i
 join read_parquet('data/payments.parquet') p on p.invoice_id = i.invoice_id) t;

select plan_year, size_segment, revenue_plan_approved, revenue_plan_model
from read_parquet('data/plan.parquet')
order by 1,2;

select plan_year, size_segment, units_plan, revenue_plan_model, revenue_plan_premium, revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
order by plan_year, size_segment;

select
  size_segment,
  count(*) as orgs_cnt
from read_parquet('data/orgs.parquet')
group by 1
order by 1;

select plan_year, size_segment, units_plan, units_basis,
       revenue_plan_model, revenue_plan_premium, revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
where plan_year = 2024
order by size_segment;

select planned_renewal_month, count(*) as n
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select plan_year, size_segment, units_plan, revision_date
from read_parquet('data/plan.parquet')
order by plan_year, size_segment;

select
  planned_renewal_month,
  count(*) as subs_planned
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select
  strftime(start_date, '%m') as start_month,
  count(*) as cnt
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select
  strftime(end_date, '%Y-%m') as end_month,
  count(*) as cnt
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select planned_renewal_month, count(*) as n_subs
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select
  date_trunc('month', start_date) as start_month,
  count(*) as n_new_subs
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select
  duration_months,
  count(*) as n
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select
  min(paid_at), max(paid_at)
from read_parquet('data/payments.parquet')

-- 1) Наивная средняя длительность подписки (по duration_months), в годах
select avg(duration_months) / 12.0 as lt_naive_avg_years
from read_parquet('data/subscriptions.parquet');

-- 2) Средний суммарный "стаж" организации (сумма длительностей всех её подписок), в годах
with org_tenure as (
  select org_id, sum(duration_months) as total_months
  from read_parquet('data/subscriptions.parquet')
  group by org_id
)
select avg(total_months) / 12.0 as lt_org_avg_years
from org_tenure;

-- Метод A: наивно, по всем подписках без учёта цепочек (среднее duration одной подписки)
select round(avg(duration_months)/12.0, 3) as lt_years_simple
from read_parquet('data/subscriptions.parquet');

-- Метод B: по органайзации — суммарная длительность всех подписок (цепочка) / 12,
-- по всем org, включая ещё активных (без учёта цензурирования)
with org_total as (
  select org_id, sum(duration_months) as total_months
  from read_parquet('data/subscriptions.parquet')
  group by org_id
)
select round(avg(total_months)/12.0, 3) as lt_years_org_naive
from org_total;

-- Метод C: только по органам, которые реально закрылись (liquidated),
-- полный жизненный цикл от регистрации до ликвидации
select round(avg(date_diff('day', registered_at, liquidated_at))/365.25, 3) as lt_years_completed_only
from read_parquet('data/orgs.parquet')
where liquidated_at is not null;
